\begin{lemma}
\label{lemma-properties-valuation}
Let $A$ be a valuation ring. The valuation $v : A -\{0\} \to \Gamma_{\geq 0}$
has the following properties:
\begin{enumerate}
\item $v(a) = 0 \Leftrightarrow a \in A^*$,
\item $v(ab) = v(a) + v(b)$,
\item $v(a + b) \geq \min(v(a), v(b))$ provided $a + b \not = 0$.
\end{enumerate}
\end{lemma}

\begin{proof}
Omitted.
\end{proof}

