\begin{lemma}
\label{lemma-ideals-valuation-ring}
Let $A$ be a valuation ring.
Ideals in $A$ correspond $1 - 1$ with ideals of $\Gamma$.
This bijection is inclusion preserving, and maps prime
ideals to prime ideals.
\end{lemma}

\begin{proof}
Omitted.
\end{proof}

